changeSet.sql:
UPDATE admin_settings_feature_toggle_overrides
SET overrides = (overrides::jsonb - 'enableGenericCaseList')::text
WHERE jsonb_exists(overrides::jsonb, 'enableGenericCaseList');

UPDATE admin_settings_feature_toggle_overrides
SET overrides = JSON_REMOVE(overrides, '$.enableGenericCaseList')
WHERE JSON_CONTAINS_PATH(overrides, 'one', '$.enableGenericCaseList') = 1;

INSERT IGNORE INTO admin_settings_feature_toggle_overrides (id, overrides)
VALUES ('singleton', '{}');

UPDATE admin_settings_feature_toggle_overrides
SET overrides = JSON_SET(overrides, '$.showAllCaseDefinitionsInMenu', CAST('true' AS JSON))
WHERE id = 'singleton'
AND JSON_CONTAINS_PATH(overrides, 'one', '$.showAllCaseDefinitionsInMenu') = 0;
